inputs = ['aizz', 'hxzc', 'zhja', 'bkfuf', 'ixeacu']
outputs = ['adzz', 'avxzc', 'zavja', 'zgffdfuf', 'dxeacu']

print("Input -> Output differences:")
for i, (inp, out) in enumerate(zip(inputs, outputs)):
    print(f"{i}: '{inp}' -> '{out}'")
    # Find positions where they differ
    for j, (c_in, c_out) in enumerate(zip(inp, out)):
        if c_in != c_out:
            print(f"  Position {j}: '{c_in}' -> '{c_out}'")
    # Check lengths
    if len(inp) != len(out):
        print(f"  Length change: {len(inp)} -> {len(out)}")

